import{_ as d,o as a,c as e,ah as o}from"./chunks/framework.Yx0DUrwu.js";const m=JSON.parse('{"title":"固有免疫","description":"","frontmatter":{},"headers":[],"relativePath":"biology/innate-immunity.md","filePath":"biology/innate-immunity.md","lastUpdated":1787830595000}'),r={name:"biology/innate-immunity.md"};function c(n,t,i,l,s,h){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="固有免疫" tabindex="-1">固有免疫 <a class="header-anchor" href="#固有免疫" aria-label="Permalink to &quot;固有免疫&quot;">​</a></h1><p>固有免疫是免疫系统的快速响应层。它先通过屏障阻止入侵；一旦病原体或组织损伤突破屏障，补体、吞噬细胞、模式识别受体、炎症因子、干扰素、NK 细胞和固有淋巴样细胞会在小时级别启动防御 [1]。</p><h2 id="一张地图" tabindex="-1">一张地图 <a class="header-anchor" href="#一张地图" aria-label="Permalink to &quot;一张地图&quot;">​</a></h2><div class="flow-strip"><span>上皮屏障</span><span>抗菌分子</span><span>补体标记</span><span>吞噬杀伤</span><span>模式识别受体感知</span><span>炎症募集</span><span>干扰素抗病毒</span><span>NK / 固有淋巴样细胞效应</span></div><h2 id="屏障与补体" tabindex="-1">屏障与补体 <a class="header-anchor" href="#屏障与补体" aria-label="Permalink to &quot;屏障与补体&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>关键组成</th><th>主要作用</th><th>单细胞解读线索</th></tr></thead><tbody><tr><td>物理屏障</td><td>皮肤、黏膜上皮、黏液、紧密连接</td><td>阻止微生物进入组织。</td><td>上皮应激、干扰素刺激基因、抗菌基因。</td></tr><tr><td>化学防御</td><td>防御素、溶菌酶、抗菌肽</td><td>直接抑制或杀伤微生物。</td><td>上皮细胞和髓系细胞的抗菌程序。</td></tr><tr><td>补体</td><td>经典途径、凝集素途径、旁路途径</td><td>调理作用、炎症放大、膜攻击复合物。</td><td><code>C1QA</code>, <code>C1QB</code>, <code>C1QC</code>, <code>C3</code> 和补体受体基因。</td></tr><tr><td>吞噬</td><td>中性粒细胞、巨噬细胞、单核细胞</td><td>摄取并清除病原体和碎片。</td><td><code>LYZ</code>, <code>S100A8</code>, <code>S100A9</code>, <code>FCGR3A</code>, <code>MARCO</code>, <code>MRC1</code> 等。</td></tr></tbody></table><p>补体可以理解为血浆中的“快速标记和放大系统”：C3b 把目标标记给吞噬细胞，C3a/C5a 招募和激活炎症细胞，终末通路可在部分病原体膜上形成孔道 [1]。</p><h2 id="模式识别受体" tabindex="-1">模式识别受体 <a class="header-anchor" href="#模式识别受体" aria-label="Permalink to &quot;模式识别受体&quot;">​</a></h2><p>固有免疫不是“非特异”的简单反射，而是通过模式识别受体（PRR）识别病原相关分子模式（PAMP）和损伤相关分子模式（DAMP）。常见模式包括：</p><table tabindex="0"><thead><tr><th>受体家族</th><th>常见识别对象</th><th>典型下游</th><th>单细胞常见现象</th></tr></thead><tbody><tr><td>TLR</td><td>细菌 LPS、鞭毛蛋白、CpG DNA、病毒 RNA</td><td>NF-kB、AP-1、IRF</td><td>炎症性细胞因子和 I 型干扰素程序。</td></tr><tr><td>NLR</td><td>细菌产物、细胞应激</td><td>炎症小体、IL-1 家族</td><td><code>IL1B</code>, <code>NLRP3</code>, <code>CASP1</code> 相关炎症状态。</td></tr><tr><td>RLR</td><td>胞质病毒 RNA</td><td>MAVS、IRF3/7</td><td><code>IFIT1</code>, <code>ISG15</code>, <code>MX1</code>, <code>OAS1</code>。</td></tr><tr><td>cGAS-STING</td><td>胞质 DNA</td><td>TBK1、IRF3</td><td>DNA 损伤、病毒感染和肿瘤炎症。</td></tr></tbody></table><h2 id="炎症与细胞募集" tabindex="-1">炎症与细胞募集 <a class="header-anchor" href="#炎症与细胞募集" aria-label="Permalink to &quot;炎症与细胞募集&quot;">​</a></h2><p>炎症的逻辑是“定位问题，招募细胞，限制损伤，清除威胁，启动修复”。巨噬细胞和树突细胞产生细胞因子和趋化因子；内皮细胞上调黏附分子；中性粒细胞和单核细胞穿过血管壁进入组织。</p><div class="check-grid"><article><strong>TNF / IL-1 / IL-6</strong><span>驱动局部炎症、急性期反应和内皮活化；过强时可导致系统性炎症损伤。</span></article><article><strong>CXCL / CCL 趋化因子</strong><span>决定不同白细胞进入组织的路线，例如中性粒细胞、单核细胞、T 细胞的募集。</span></article><article><strong>I 型干扰素</strong><span>诱导抗病毒状态，也可在自身免疫和肿瘤微环境中形成长期炎症背景。</span></article><article><strong>NK 细胞</strong><span>通过激活性/抑制性受体识别缺失自身 MHC 或表达应激配体的靶细胞。</span></article></div><h2 id="nk-和-ilc" tabindex="-1">NK 和 ILC <a class="header-anchor" href="#nk-和-ilc" aria-label="Permalink to &quot;NK 和 ILC&quot;">​</a></h2><p>NK 细胞偏向细胞毒杀伤和 IFN-gamma 产生；ILC1、ILC2、ILC3 是固有淋巴样细胞的主要类型，分别与 Th1、Th2、Th17 类似，参与胞内病原、寄生虫/组织修复、黏膜屏障和胞外菌/真菌应答。单细胞数据中，ILC 与 T 细胞标志基因可能部分重叠，需要结合 <code>TRAC</code>, <code>CD3D</code>, <code>KLRD1</code>, <code>KIT</code>, <code>IL7R</code>, <code>RORC</code>, <code>GATA3</code>, <code>TBX21</code> 等组合判断。</p><h2 id="自检问题" tabindex="-1">自检问题 <a class="header-anchor" href="#自检问题" aria-label="Permalink to &quot;自检问题&quot;">​</a></h2><ol><li>病原相关分子模式（PAMP）和损伤相关分子模式（DAMP）的区别是什么？</li><li>补体的三类主要效应是什么？</li><li>为什么 I 型干扰素程序不能简单等同于病毒感染？</li><li>NK 细胞如何避免攻击健康细胞？</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>[1] Murphy, K. &amp; Weaver, C. <em>Janeway&#39;s Immunobiology</em>. 9th ed. Garland Science (2017). 中文版：《詹韦免疫生物学：原书第九版》，科学出版社，2022。</p>',19)])])}const b=d(r,[["render",c]]);export{m as __pageData,b as default};
